10	/// Package identity across ecosystems.
11	#[derive(Clone, Debug, PartialEq, Eq, Hash, JsonSchema)]
12	#[schemars(with = "String")]
13	pub enum PackageId {
14	    Bare(String),
15	    Prefixed { ecosystem: Ecosystem, name: String },
16	}
17	
18	impl PackageId {
19	    /// Parses package identity string.
20	    ///
21	    /// # Errors
22	    ///
23	    /// Returns `Err` if `s` is empty, starts with `/`, contains `..`, or has a known ecosystem prefix followed by an empty name.
24	    pub fn parse(s: &str) -> Result<Self, PackageIdParseError> {
25	        if s.is_empty() {
26	            return Err(PackageIdParseError::Empty);
27	        }
28	        if s.starts_with('/') {
29	            return Err(PackageIdParseError::LeadingSlash { raw: s.to_string() });
30	        }
31	        if s.starts_with('-') {
32	            return Err(PackageIdParseError::LeadingHyphen { raw: s.to_string() });
33	        }
34	        if s.contains("..") {
35	            return Err(PackageIdParseError::PathTraversal { raw: s.to_string() });
36	        }
37	
38	        if let Some((prefix, remainder)) = s.split_once(':') {
39	            if let Some(ecosystem) = Ecosystem::from_prefix(prefix) {
40	                Self::validate_prefixed_remainder(s, prefix, remainder)?;
41	                return Ok(PackageId::Prefixed {
42	                    ecosystem,
43	                    name: remainder.to_string(),
44	                });
45	            }
46	        }
47	
48	        if let Some((prefix, remainder)) = s.split_once('/') {
49	            if let Some(ecosystem) = Ecosystem::from_prefix(prefix) {
50	                Self::validate_prefixed_remainder(s, prefix, remainder)?;
51	                return Ok(PackageId::Prefixed {
52	                    ecosystem,
53	                    name: remainder.to_string(),
54	                });
55	            }
56	        }
57	
58	        Ok(PackageId::Bare(s.to_string()))
59	    }
60	
61	    /// Shared validation for the remainder of an ecosystem-prefixed id (the part
62	    /// after the `:` or `/` separator), used by both prefixed forms in [`Self::parse`].
63	    fn validate_prefixed_remainder(raw: &str, prefix: &str, remainder: &str) -> Result<(), PackageIdParseError> {
64	        if remainder.is_empty() {
65	            return Err(PackageIdParseError::EmptyNameAfterPrefix {
66	                raw: raw.to_string(),
67	                prefix: prefix.to_string(),
68	            });
69	        }
70	        if remainder.starts_with('-') {
71	            return Err(PackageIdParseError::LeadingHyphen { raw: raw.to_string() });
72	        }
73	        if remainder.contains("..") {
74	            return Err(PackageIdParseError::PathTraversal { raw: raw.to_string() });
75	        }
76	        Ok(())
77	    }
78	
79	    /// Returns the canonical display form: bare names as-is, prefixed ids as `ecosystem/name`.
80	    pub fn display_name(&self) -> String {
81	        match self {
82	            PackageId::Bare(name) => name.clone(),
83	            PackageId::Prefixed { ecosystem, name } => {
84	                format!("{}/{}", ecosystem.prefix(), name)
85	            }
86	        }
87	    }
88	
89	    /// Returns the ecosystem this id is scoped to, or `None` for a [`PackageId::Bare`] id.
90	    pub fn ecosystem(&self) -> Option<Ecosystem> {
91	        match self {
92	            PackageId::Bare(_) => None,
93	            PackageId::Prefixed { ecosystem, .. } => Some(*ecosystem),
94	        }
95	    }
96	
97	    /// Returns the package name without any ecosystem prefix.
98	    pub fn name(&self) -> &str {
99	        match self {
100	            PackageId::Bare(name) => name,
101	            PackageId::Prefixed { name, .. } => name,
102	        }
103	    }
104	
105	    /// Weak "could be the same package" check, not strict equality.
106	    ///
107	    /// `Bare(x)` matches any `Prefixed(_, x)` (bare is an ecosystem wildcard);
108	    /// `Prefixed(e1, x)` matches `Prefixed(e2, x)` only if `e1 == e2`; exact
109	    /// equality always matches.
110	    ///
111	    /// **Caller contract**: in a polyglot workspace, a bare lookup can match
112	    /// packages in two or more ecosystems (e.g. `foo` in both Cargo and npm).
113	    /// Callers must collect *all* matches and error on 2+ — see
114	    /// `aggregate::resolve_target_package`'s `AmbiguousName` pattern — never
115	    /// take the first match silently. A plain existence check (`.any()`) is
116	    /// safe only because the aggregation layer already rejects ambiguous
117	    /// references upstream.
118	    pub fn matches(&self, other: &Self) -> bool {
119	        if self == other {
120	            return true;
121	        }
122	        if self.name() == other.name() {
123	            match (self.ecosystem(), other.ecosystem()) {
124	                (None, _) | (_, None) => true,
125	                (Some(e1), Some(e2)) => e1 == e2,
126	            }
127	        } else {
128	            false
129	        }
130	    }
131	
132	    /// The single implementation of the collect-and-error pattern
133	    /// [`matches`](Self::matches)'s own doc comment requires every caller
134	    /// to hand-roll: filters `items` down to those whose id (via `id_of`)
135	    /// matches `self`, then resolves the result to exactly one, none, or
136	    /// reports the ambiguity.
137	    ///
138	    /// - `Ok(None)`: no item matches.
139	    /// - `Ok(Some(item))`: exactly one item matches -- the unambiguous case.
140	    /// - `Err(candidates)`: two or more items match. The caller decides how
141	    ///   to report this (e.g. as a domain-specific "ambiguous name" error
142	    ///   naming `self` and `candidates`) -- this method stays generic over
143	    ///   any `T` (a `Package`, a bare `PackageId`, ...) rather than forcing
144	    ///   a particular error type on every layer that needs this check.
145	    pub fn resolve_unique<'a, T>(
146	        &self,
147	        items: impl Iterator<Item = &'a T>,
148	        id_of: impl Fn(&'a T) -> &'a PackageId,
149	    ) -> Result<Option<&'a T>, Vec<&'a T>> {
150	        let matching: Vec<&'a T> = items.filter(|item| id_of(item).matches(self)).collect();
151	        match matching.len() {
152	            0 => Ok(None),
153	            1 => Ok(Some(matching[0])),
154	            _ => Err(matching),
155	        }
156	    }
157	}
