277	/// A 40-character hex Git commit SHA.
278	#[derive(Clone, Debug, PartialEq, Eq, Hash, PartialOrd, Ord, JsonSchema)]
279	#[schemars(with = "String")]
280	pub struct CommitSha(String);
281	
282	impl AsRef<str> for CommitSha {
283	    fn as_ref(&self) -> &str {
284	        &self.0
285	    }
286	}
287	
288	impl CommitSha {
289	    /// Parses a 40-character hexadecimal Git commit SHA, trimming surrounding whitespace.
290	    ///
291	    /// # Errors
292	    ///
293	    /// Returns `Err(ModelError::InvalidCommitSha)` if the trimmed input is not exactly 40 ASCII hex digits.
294	    pub fn parse(s: &str) -> Result<Self, ModelError> {
295	        let trimmed = s.trim();
296	        if trimmed.len() != 40 || !trimmed.chars().all(|c| c.is_ascii_hexdigit()) {
297	            return Err(ModelError::InvalidCommitSha {
298	                raw: s.to_string(),
299	                reason: "must be exactly 40 hexadecimal characters".to_string(),
300	            });
301	        }
302	        Ok(CommitSha(trimmed.to_lowercase()))
303	    }
304	
305	    /// Returns the full 40-character lowercase hex SHA.
306	    pub fn as_str(&self) -> &str {
307	        &self.0
308	    }
309	
310	    /// Returns the first 7 characters of the SHA, matching git's short-ref convention.
311	    pub fn short(&self) -> &str {
312	        &self.0[..7]
313	    }
314	}
