14	impl TagTemplate {
15	    pub fn parse(raw: &str) -> Result<Self, TagTemplateError> {
16	        let version_marker = "{version}";
17	        let count = raw.matches(version_marker).count();
18	        if count == 0 {
19	            if let Some(start) = raw.find('{') {
20	                if let Some(end) = raw[start..].find('}') {
21	                    let placeholder = &raw[start + 1..start + end];
22	                    return Err(TagTemplateError::UnknownPlaceholder {
23	                        template: raw.to_string(),
24	                        placeholder: placeholder.to_string(),
25	                    });
26	                }
27	            }
28	            return Err(TagTemplateError::MissingVersionPlaceholder {
29	                template: raw.to_string(),
30	            });
31	        }
32	        if count > 1 {
33	            return Err(TagTemplateError::MultipleVersionPlaceholders {
34	                template: raw.to_string(),
35	                count,
36	            });
37	        }
38	
39	        let (prefix, suffix) = raw.split_once(version_marker).unwrap();
