139	fn is_valid_git_ref_name(s: &str) -> bool {
140	    if s.is_empty() || s.starts_with('/') || s.ends_with('/') || s.contains("//") || s == "@" {
141	        return false;
142	    }
143	    // Git ref names may legally start with `-`, but every caller in this
144	    // codebase passes the rendered name as a bare positional to `git tag`
145	    // (or an equivalent CLI), whose argument parser treats a leading `-`
146	    // as an option rather than a ref name -- reject it here so a malicious
147	    // or accidental `tag-template` can never produce one.
148	    if s.starts_with('-') {
149	        return false;
150	    }
151	    if s.contains("..") || s.contains("@{") {
152	        return false;
153	    }
154	    for component in s.split('/') {
155	        if component.starts_with('.') || component.ends_with(".lock") {
156	            return false;
157	        }
158	    }
159	    for ch in s.chars() {
160	        if ch.is_ascii_control() || ch == ' ' || matches!(ch, '~' | '^' | ':' | '?' | '*' | '[' | '\\') {
161	            return false;
162	        }
163	    }
164	    true
165	}
